begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select ok(not has_schema_privilege('service_role','app_private','usage'),'worker still cannot name private schema types');
select ok(has_function_privilege('service_role','api.worker_update_outbox_v2(uuid,text,text,text,timestamptz)','execute'),'worker can execute text boundary');
select ok(not has_function_privilege('anon','api.worker_update_outbox_v2(uuid,text,text,text,timestamptz)','execute'),'anon cannot update mail');
select ok(not has_function_privilege('authenticated','api.worker_update_outbox_v2(uuid,text,text,text,timestamptz)','execute'),'users cannot update mail');
select is((select proconfig::text from pg_proc where oid='api.worker_update_outbox_v2(uuid,text,text,text,timestamptz)'::regprocedure),'{"search_path=\"\""}','definer has a fixed empty search path');
insert into app_private.email_outbox(id,dedupe_key,message_type,recipient_ref,recipient_email,payload,status,attempts,lease_until)
values ('94000000-0000-0000-0000-000000000001','text-worker-fixture','registration_received','fixture','worker@example.invalid','{}','processing',1,now()+interval '5 minutes');
set local role service_role;
select throws_ok($$select api.worker_update_outbox('94000000-0000-0000-0000-000000000001','deferred'::app_private.outbox_status)$$,'42501',null,'old argument conversion fails before the definer');
select throws_ok($$select api.worker_update_outbox_v2('94000000-0000-0000-0000-000000000001',null)$$,'22023','INVALID_OUTBOX_STATUS','null status rejected');
select throws_ok($$select api.worker_update_outbox_v2('94000000-0000-0000-0000-000000000001','pending')$$,'22023','INVALID_OUTBOX_STATUS','cannot reset an attempt with the result RPC');
select throws_ok($$select api.worker_update_outbox_v2('94000000-0000-0000-0000-000000000001','invalid')$$,'22023','INVALID_OUTBOX_STATUS','invalid text rejected internally');
select lives_ok($$select api.worker_update_outbox_v2('94000000-0000-0000-0000-000000000001','deferred',null,'RESEND_RATE_LIMIT','2026-10-31T12:00:00Z')$$,'service role persists retry through text boundary');
reset role;
select is((select status::text from app_private.email_outbox where id='94000000-0000-0000-0000-000000000001'),'deferred','retry outcome persisted');
select is((select attempts from app_private.email_outbox where id='94000000-0000-0000-0000-000000000001'),1,'status update preserves attempt counter');
select ok((select lease_until is null and next_attempt_at='2026-10-31T12:00:00Z' and last_error_code='RESEND_RATE_LIMIT' from app_private.email_outbox where id='94000000-0000-0000-0000-000000000001'),'retry time, code and lease preserved');
set local role service_role;
select lives_ok($$select api.worker_update_outbox_v2('94000000-0000-0000-0000-000000000001','accepted','fixture-provider-id')$$,'text boundary persists acceptance');
select lives_ok($$select api.worker_update_outbox_v2('94000000-0000-0000-0000-000000000001','unknown',null,'LATE_WORKER')$$,'late result cannot overwrite terminal acceptance');
reset role;
select ok((select status='accepted' and provider_id='fixture-provider-id' and accepted_at is not null from app_private.email_outbox where id='94000000-0000-0000-0000-000000000001'),'accepted identity and terminal state survive a late update');
update app_private.email_outbox set status='delivered' where id='94000000-0000-0000-0000-000000000001';
set local role service_role;
select api.worker_update_outbox_v2('94000000-0000-0000-0000-000000000001','deferred',null,'LATE_WORKER');
reset role;
select is((select status::text from app_private.email_outbox where id='94000000-0000-0000-0000-000000000001'),'delivered','delivered mail never becomes claimable');
select * from finish();
rollback;
